import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:ital,wght@0,400;0,700;1,400;1,700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type VennDiagramProps = Record<string, any>;

const VennDiagram: React.FC<VennDiagramProps> = ({
  backgroundColor = "#ffffff",
  gridColor = "#e6f0ff",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "Working Smarter, Not Harder//",
  titleFont = "Playfair Display",
  titleFontSize = 60,
  leftLabel = "Time",
  rightLabel = "Management",
  labelFontSize = 32,
  bottomLabel = "Effectiveness",
  bottomLabelFontSize = 48,
  leftColor = "#5B6CFF",
  rightColor = "#FF5B6C",
  textColor = "#1a1a1a",
}) => {
  // Load the selected title font, plus Playfair Display for the labels
  useFontLoader([titleFont, "Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Layout Calculations ---
  const isPortrait = height > width;
  const centerX = width / 2;
  const centerY = height / 2;
  
  // Circle sizing based on viewport
  const circleRadius = Math.min(width, height) * 0.22;
  const overlapDistance = circleRadius * 0.6; // Overlap amount
  const centerOffset = circleRadius - (overlapDistance / 2);

  // --- Animations ---
  
  // 1. Grid Fade In
  const gridOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });

  // 2. Title Animation
  const titleY = interpolate(frame, [10, 40], [height * 0.1, height * 0.15], { extrapolateRight: "clamp", easing: (t) => t * (2 - t) });
  const titleOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });
  const lineProgress = interpolate(frame, [25, 55], [0, 100], { extrapolateRight: "clamp" });

  // 3. Circles Spring
  const leftCircleSpring = spring({ 
    frame: frame - 30, 
    fps, 
    config: { damping: 12, stiffness: 80 } 
  });
  const rightCircleSpring = spring({ 
    frame: frame - 35, 
    fps, 
    config: { damping: 12, stiffness: 80 } 
  });
  
  const leftCircleX = interpolate(leftCircleSpring, [0, 1], [centerX - centerOffset - 200, centerX - centerOffset]);
  const rightCircleX = interpolate(rightCircleSpring, [0, 1], [centerX + centerOffset + 200, centerX + centerOffset]);
  const circleScale = interpolate(leftCircleSpring, [0, 1], [0, 1]); // Both use similar timing for scale

  // 4. Labels Fade In
  const labelOpacity = interpolate(frame, [70, 90], [0, 1], { extrapolateRight: "clamp" });

  // 5. Pointer Animation
  const pointerStartFrame = 90;
  const pointerGrowth = spring({ 
    frame: frame - pointerStartFrame, 
    fps, 
    config: { damping: 15 } 
  });
  const pointerHeight = interpolate(pointerGrowth, [0, 1], [0, circleRadius * 1.2]);
  
  const bottomLabelOpacity = interpolate(frame, [pointerStartFrame + 20, pointerStartFrame + 40], [0, 1], { extrapolateRight: "clamp" });

  // --- Styles ---
  const bg = transparentBackground ? "transparent" : backgroundColor;
  
  const titleLines = titleText.split("\n");

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      
      {/* Grid Background */}
      <AbsoluteFill
        style={{
          opacity: gridOpacity,
          backgroundImage: `
            linear-gradient(${gridColor} 1px, transparent 1px),
            linear-gradient(90deg, ${gridColor} 1px, transparent 1px)
          `,
          backgroundSize: '40px 40px',
        }}
      />

      {/* Title Section */}
      <div
        style={{
          position: "absolute",
          top: titleY,
          left: width * 0.1,
          width: width * 0.8,
          opacity: titleOpacity,
          fontFamily: titleFont,
          color: textColor,
        }}
      >
        {/* Top Line */}
        <div style={{ width: "100%", height: 2, background: "#ccc", marginBottom: 15, transform: `scaleX(${lineProgress / 100})`, transformOrigin: "left" }} />
        
        {titleLines.map((line, i) => (
          <h1 
            key={i}
            style={{ 
              fontSize: titleFontSize, 
              margin: 0, 
              lineHeight: 1.2,
              fontWeight: 700,
              fontStyle: "italic" 
            }}
          >
            {line}
          </h1>
        ))}

        {/* Bottom Line */}
        <div style={{ width: "100%", height: 2, background: "#ccc", marginTop: 15, transform: `scaleX(${lineProgress / 100})`, transformOrigin: "right" }} />
      </div>

      {/* Venn Diagram Container */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
        <div style={{ position: "relative", width: width, height: height }}>
          
          {/* Left Circle (Time) */}
          <div
            style={{
              position: "absolute",
              left: leftCircleX,
              top: centerY,
              width: circleRadius * 2,
              height: circleRadius * 2,
              borderRadius: "50%",
              backgroundColor: leftColor,
              transform: `translate(-50%, -50%) scale(${circleScale})`,
              mixBlendMode: "multiply",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              zIndex: 10,
            }}
          >
            <span style={{ 
              color: "white", 
              fontFamily: "Playfair Display", 
              fontSize: labelFontSize, 
              opacity: labelOpacity,
              transform: "translateX(-40px)" // Push label slightly left to be in non-overlapped area
            }}>
              {leftLabel}
            </span>
          </div>

          {/* Right Circle (Management) */}
          <div
            style={{
              position: "absolute",
              left: rightCircleX,
              top: centerY,
              width: circleRadius * 2,
              height: circleRadius * 2,
              borderRadius: "50%",
              backgroundColor: rightColor,
              transform: `translate(-50%, -50%) scale(${circleScale})`,
              mixBlendMode: "multiply",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              zIndex: 10,
            }}
          >
             <span style={{ 
              color: "white", 
              fontFamily: "Playfair Display", 
              fontSize: labelFontSize, 
              opacity: labelOpacity,
              transform: "translateX(40px)" // Push label slightly right
            }}>
              {rightLabel}
            </span>
          </div>

          {/* Pointer Line */}
          <div
            style={{
              position: "absolute",
              left: centerX,
              top: centerY,
              width: 2,
              height: pointerHeight,
              backgroundColor: "#333",
              transformOrigin: "top",
              zIndex: 20,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "space-between"
            }}
          >
             {/* Top Dot */}
            <div style={{ 
              width: 8, height: 8, borderRadius: "50%", background: "white", border: "2px solid #333", 
              transform: `scale(${pointerGrowth})`, marginTop: -4 
            }} />
            
             {/* Bottom Dot */}
             <div style={{ 
              width: 8, height: 8, borderRadius: "50%", background: "white", border: "2px solid #333", 
              transform: `scale(${pointerGrowth})`, marginBottom: -4,
              opacity: pointerGrowth > 0.5 ? 1 : 0
            }} />
          </div>

          {/* Effectiveness Label */}
          <div
             style={{
              position: "absolute",
              left: centerX,
              top: centerY + circleRadius * 1.2 + 20,
              transform: "translateX(-50%)",
              opacity: bottomLabelOpacity,
              fontFamily: "Playfair Display",
              fontSize: bottomLabelFontSize,
              fontStyle: "italic",
              color: textColor,
              zIndex: 20,
             }}
          >
            {bottomLabel}
          </div>

        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default VennDiagram;